CREATE TABLE IF NOT EXISTS drops (id TEXT PRIMARY KEY, title TEXT NOT NULL, starts INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS products (id TEXT PRIMARY KEY, name TEXT NOT NULL, category TEXT NOT NULL, size TEXT NOT NULL, price INTEGER NOT NULL CHECK(price>=0), measures TEXT NOT NULL, condition TEXT NOT NULL, image TEXT NOT NULL, drop_id TEXT NOT NULL REFERENCES drops(id), sold INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS orders (id TEXT PRIMARY KEY, request_key TEXT UNIQUE NOT NULL, name TEXT NOT NULL, contact TEXT NOT NULL, delivery TEXT NOT NULL, address TEXT NOT NULL, total INTEGER NOT NULL, fee INTEGER NOT NULL, status TEXT NOT NULL, expires INTEGER NOT NULL, receipt TEXT, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS items (order_id TEXT NOT NULL REFERENCES orders(id), product TEXT NOT NULL REFERENCES products(id), amount INTEGER NOT NULL, PRIMARY KEY(order_id,product));
CREATE TABLE IF NOT EXISTS holds (product TEXT NOT NULL PRIMARY KEY REFERENCES products(id), owner TEXT NOT NULL, expires INTEGER NOT NULL, token TEXT NOT NULL DEFAULT (lower(hex(randomblob(16)))));
CREATE TABLE IF NOT EXISTS queue (id INTEGER PRIMARY KEY AUTOINCREMENT, product TEXT NOT NULL REFERENCES products(id), handle TEXT NOT NULL, minutes INTEGER NOT NULL, UNIQUE(product,handle));
CREATE TABLE IF NOT EXISTS audit (id INTEGER PRIMARY KEY AUTOINCREMENT, action TEXT NOT NULL, detail TEXT NOT NULL, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS settings (id TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS staff (id TEXT PRIMARY KEY, digest TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS payment_links (order_id TEXT NOT NULL PRIMARY KEY REFERENCES orders(id), url TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS wompi_events (tx TEXT NOT NULL PRIMARY KEY, order_id TEXT NOT NULL, amount INTEGER NOT NULL, created INTEGER NOT NULL);
